{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-06",
  "sketch": {
    "components": ["Mobile app", "Notification composer service", "Order service", "Device token registry", "OS notification centre"],
    "dataStores": ["Device token registry", "Order records"],
    "externalServices": ["Apple Push Notification service", "Firebase Cloud Messaging"],
    "trustBoundaries": ["Backend to push provider", "Push provider to device OS", "Locked device screen to physical bystander"],
    "dataClasses": ["pii"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Order contents and home address readable on a locked phone by anyone nearby",
      "scenario": "Anyone with line of sight to a locked handset - a colleague, a flatmate, someone on a train, or a thief holding a stolen phone - reads the full order contents and the delivery address without unlocking the device. For orders that reveal health, dietary, religious or adult-product details this is sensitive personal data, and the address links it to where the customer lives.",
      "component": "OS notification centre / lock screen presentation",
      "likelihood": 5,
      "impact": 3,
      "evidence": [
        {
          "quote": "The app sends push notifications that include the full order contents and delivery address. Notifications show on the lock screen by default."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-359", "CWE-200"],
      "plainLanguage": "Someone glancing at a locked phone can see exactly what the customer ordered and where they live.",
      "requirement": {
        "title": "Keep order details out of the lock-screen preview",
        "given": "a customer's device is locked",
        "when": "an order notification arrives",
        "then": "the visible text contains no order line items and no delivery address, and full details are only revealed after the device is unlocked and the user is authenticated in the app"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Push providers receive customer order and address data in the payload",
      "scenario": "Because the notification body carries the order contents and delivery address, that personal data is handed to Apple and Google push infrastructure in transit and may be retained or logged there. An attacker who compromises the push provider credentials, or an insider at the provider, can read customer orders and home addresses at scale without ever touching our systems.",
      "component": "Backend to APNs/FCM push payload",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "The app sends push notifications that include the full order contents and delivery address."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-311", "CWE-359"],
      "plainLanguage": "Sending the order and address inside the push message means third-party push services get to see that personal data too.",
      "requirement": {
        "title": "Send a reference, not the personal data, through push providers",
        "given": "the backend needs to notify a customer about an order",
        "when": "it builds the push payload for APNs or FCM",
        "then": "the payload contains only a non-guessable order reference and an event type, and the app fetches order contents and address over an authenticated API call"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Stale or reassigned device token delivers one customer's order to another person",
      "scenario": "Device tokens outlive sessions. If the registry is not cleared on logout, account switch, app reinstall or device resale, the backend keeps pushing order contents and the delivery address to a handset now held by a different person. The new holder learns the previous customer's purchases and home address with no attack effort at all.",
      "component": "Device token registry",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "The app sends push notifications that include the full order contents and delivery address."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-613"],
      "plainLanguage": "If a phone changes hands or someone logs out, old notifications with another customer's orders can still land on it.",
      "requirement": {
        "title": "Unbind device tokens from the account when the session ends",
        "given": "a device token is registered to a customer account",
        "when": "the customer logs out, the account on the device changes, or the push provider reports the token invalid or unregistered",
        "then": "the token is deleted from the registry immediately and no further order notifications are sent to it"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Notification send endpoint can be driven to target any order or any device",
      "scenario": "An internal caller or an attacker who reaches the notification service can ask it to send a notification for an arbitrary order id to an arbitrary device token. Since the service renders the full order contents and delivery address into the message, this turns the notifier into an oracle for reading any customer's order and address - an authorisation bypass rather than just a messaging bug.",
      "component": "Notification composer service",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "Push notifications with order details"
        },
        {
          "quote": "The app sends push notifications that include the full order contents and delivery address."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-639", "CWE-862"],
      "plainLanguage": "If the notification sender trusts whoever calls it, someone could use it to read any customer's order and address.",
      "requirement": {
        "title": "Check the order belongs to the target device's owner",
        "given": "a request to send an order notification",
        "when": "the notification service resolves the order and the destination device token",
        "then": "it verifies the order belongs to the account that owns that token, rejects the request otherwise, and never accepts caller-supplied notification body text"
      }
    },
    {
      "stride": "Tampering",
      "title": "Order text rendered into notifications can carry attacker-chosen content",
      "scenario": "Order line items and the delivery address originate from customer or merchant input. An attacker places an order whose item name or address field contains misleading text (for example a fake 'Your payment failed, call this number' message) or control characters. Because the full contents are rendered verbatim into a notification the recipient trusts, this becomes a phishing channel delivered through our own brand, and malformed input can break notification rendering.",
      "component": "Notification composer service",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        {
          "quote": "The app sends push notifications that include the full order contents and delivery address."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-74", "CWE-116"],
      "plainLanguage": "Text typed into an order can show up word-for-word in a notification, so it could be used to fake a trusted message.",
      "requirement": {
        "title": "Sanitise and bound any order text used in a notification",
        "given": "order item names or address fields are included in notification text",
        "when": "the notification body is composed",
        "then": "the values are escaped, stripped of control characters and newlines, truncated to a fixed length, and placed only in a fixed template that the attacker cannot restructure"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Order contents and address copied into push delivery logs",
      "scenario": "The notification payload is the personal data itself, so every request log, retry record, error report and support trace in the notification path stores customers' order contents and home addresses. Anyone with log or observability access - a wide internal audience, plus any attacker who reaches the log store - can read customer purchases and addresses in bulk, far beyond the audience allowed to view orders in the app.",
      "component": "Notification composer service logs and telemetry",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        {
          "quote": "The app sends push notifications that include the full order contents and delivery address."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-532"],
      "plainLanguage": "Because the personal data travels inside the message, it ends up in logs that lots of people can read.",
      "requirement": {
        "title": "Never log notification bodies containing order data",
        "given": "the notification service logs a send attempt, retry or failure",
        "when": "the log record is written",
        "then": "it records only the order reference, device token identifier and status code, with order line items and delivery address redacted"
      }
    }
  ]
}
